*{box-sizing:border-box}html,body{height:100%;margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,select{font:inherit;color:inherit}button{border:1px solid var(--line);background:#102027;border-radius:8px;padding:7px 10px;cursor:pointer;transition:border-color .15s,background .15s}button:hover{border-color:#38606b;background:#15313a}button:focus-visible,select:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}.topbar{height:64px;display:flex;align-items:center;gap:16px;padding:0 20px;border-bottom:1px solid var(--line);background:#09151a}.brand{display:flex;align-items:center;gap:10px}.brand-mark{width:32px;height:32px;display:grid;place-items:center;border-radius:10px;background:linear-gradient(135deg,#40d9a4,#3994a8);color:#052019;font-weight:900}.brand-copy b{display:block;font-size:14px;letter-spacing:.02em}.brand-copy span{display:block;color:var(--muted);font-size:9px;letter-spacing:.16em;text-transform:uppercase;margin-top:2px}.instrument{border-left:1px solid var(--line);padding-left:16px}.instrument b{font-size:14px;letter-spacing:.06em}.instrument span{display:block;margin-top:2px;color:var(--muted);font-size:10px}.spacer{flex:1}.read-only{border:1px solid #35575d;background:#102329;color:#a9c2c6;border-radius:99px;padding:6px 10px;font-size:10px;letter-spacing:.07em;text-transform:uppercase;white-space:nowrap}.connection{display:flex;align-items:center;gap:7px;border:1px solid var(--line);border-radius:99px;padding:6px 10px;font-size:10px;letter-spacing:.08em;text-transform:uppercase;white-space:nowrap}.led{width:7px;height:7px;border-radius:50%;background:#70848a}.connection.live{border-color:#276752;background:#10271f;color:#93edc0}.connection.live .led{background:var(--green);box-shadow:0 0 10px #42d6a0aa}.connection.reconnecting{border-color:#705625;color:#f5cd7b}.connection.reconnecting .led{background:var(--amber);animation:pulse 1s infinite}.connection.stopped{border-color:#663a45;color:#ff9ba5}.connection.stopped .led{background:var(--red)}@keyframes pulse{50%{opacity:.35}}.top-actions{display:flex;gap:7px}.top-actions button{font-size:11px}.workspace{height:calc(100% - 64px);min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 330px}.main{min-width:0;min-height:0;padding:14px 16px;display:flex;flex-direction:column;gap:10px}.toolbar{display:flex;align-items:center;gap:6px;min-height:34px;flex-wrap:wrap}.toolbar .group{display:flex;gap:4px}.toolbar button{font-size:10px;padding:6px 9px}.toolbar button.active{border-color:#338371;color:#86ebc4;background:#12352d}.toolbar .separator{width:1px;height:22px;background:var(--line);margin:0 5px}.toolbar select{background:#102027;border:1px solid var(--line);border-radius:8px;padding:6px 25px 6px 9px;font-size:10px}.toolbar-note{margin-left:auto;color:var(--muted);font-size:10px}.stats{display:grid;grid-template-columns:repeat(5,minmax(110px,1fr));gap:8px}.stat{min-width:0;border:1px solid var(--line);border-radius:9px;padding:8px 10px;background:linear-gradient(145deg,#102027,#0b171c)}.stat label{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:9px;letter-spacing:.12em;text-transform:uppercase}.stat b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px;font-size:14px;font-variant-numeric:tabular-nums}.stat small{display:block;margin-top:3px;color:var(--muted);font-size:9px;white-space:nowrap}.pos{color:var(--green)!important}.neg{color:var(--red)!important}.chart-frame{position:relative;flex:1;min-height:320px;overflow:hidden;border:1px solid var(--line);border-radius:12px;background:#081319;box-shadow:var(--shadow)}.chart-title{position:absolute;z-index:2;top:10px;left:13px;display:flex;align-items:center;gap:8px;pointer-events:none}.chart-title b{font-size:11px}.chart-title span{font-size:9px;color:var(--muted)}canvas{display:block;width:100%;height:100%;touch-action:none;cursor:crosshair}.tooltip{position:absolute;z-index:3;display:none;pointer-events:none;min-width:195px;padding:9px 10px;border:1px solid #35515a;border-radius:8px;background:#0a171eec;box-shadow:var(--shadow);font-size:10px;backdrop-filter:blur(8px)}.tooltip-head{display:flex;justify-content:space-between;gap:12px;padding-bottom:5px;margin-bottom:6px;border-bottom:1px solid var(--line);font-weight:700}.tooltip-grid{display:grid;grid-template-columns:1fr 1fr;gap:4px 10px;color:var(--muted)}.tooltip-grid b{float:right;color:var(--text);font-weight:600;font-variant-numeric:tabular-nums}.chart-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;color:var(--muted);font-size:9px;min-height:18px}.chart-footer strong{color:#c5d8da;font-weight:600}.sidebar{min-height:0;overflow:auto;border-left:1px solid var(--line);background:#0a161b}.side-section{padding:13px 13px 12px;border-bottom:1px solid var(--line)}.side-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;font-size:10px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.side-title small{color:var(--muted);font-size:9px;font-weight:500;letter-spacing:0;text-transform:none}.quote-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.quote-box{min-width:0;padding:8px;border:1px solid #20363d;border-radius:8px;background:#0d1d23}.quote-box label{display:block;color:var(--muted);font-size:8px;letter-spacing:.11em;text-transform:uppercase}.quote-box b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px;font-size:12px;font-variant-numeric:tabular-nums}.metric-list{display:grid;grid-template-columns:1fr auto;gap:8px 10px;margin-top:10px;font-size:10px}.metric-list span{color:var(--muted)}.metric-list b{font-variant-numeric:tabular-nums;text-align:right}.flow-line{height:7px;display:flex;overflow:hidden;margin-top:9px;border-radius:99px;background:#39232a}.flow-buy{height:100%;width:50%;background:var(--green);transition:width .12s}.flow-sell{height:100%;flex:1;background:var(--red)}.flow-legend{display:flex;justify-content:space-between;margin-top:5px;color:var(--muted);font-size:8px}.tape{padding-top:12px}.tape-list{display:flex;flex-direction:column;gap:2px}.tape-row{display:grid;grid-template-columns:52px 1fr 1fr 1fr;gap:5px;align-items:center;padding:5px 4px;border-radius:5px;font-size:9px;font-variant-numeric:tabular-nums}.tape-row:nth-child(even){background:#ffffff04}.tape-row .time{color:var(--muted)}.tape-row .price{text-align:right;font-weight:700}.tape-row .size{text-align:right;color:#b7c7c9}.side-tag{font-size:8px;font-weight:800;text-transform:uppercase}.side-tag.buy{color:var(--green)}.side-tag.sell{color:var(--red)}.side-tag.unknown{color:var(--muted)}.empty{padding:18px 6px;text-align:center;color:var(--muted);font-size:10px}.paper{border:1px solid #344c45;border-radius:9px;background:linear-gradient(145deg,#10221d,#0c1919);padding:10px}.paper-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.paper-head b{font-size:10px;letter-spacing:.1em;text-transform:uppercase}.paper-badge{color:#92ebbf;border:1px solid #276752;background:#10271f;border-radius:99px;padding:3px 6px;font-size:8px;letter-spacing:.08em}.paper-equity{display:flex;justify-content:space-between;align-items:baseline;margin:10px 0 8px}.paper-equity strong{font-size:18px;font-variant-numeric:tabular-nums}.paper-equity span{font-size:10px;font-weight:700}.paper-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px}.paper-cell{padding:6px;border-radius:6px;background:#ffffff08}.paper-cell label{display:block;color:var(--muted);font-size:8px;text-transform:uppercase;letter-spacing:.08em}.paper-cell b{display:block;margin-top:3px;font-size:10px;font-variant-numeric:tabular-nums}.fills{margin-top:9px;padding-top:8px;border-top:1px solid #294139}.fill-row{display:flex;justify-content:space-between;gap:8px;padding:3px 0;color:#b3c4c2;font-size:9px}.fill-row strong{color:var(--text);font-weight:700}.disclaimer{margin-top:9px;color:#9cacae;font-size:9px;line-height:1.5}.notice{border:1px solid #584522;border-radius:8px;background:#5b431418;color:#d9c99f;padding:8px 9px;font-size:9px;line-height:1.45}.hide{display:none!important}
@media(max-width:1120px){.workspace{grid-template-columns:minmax(0,1fr) 300px}.stats{grid-template-columns:repeat(3,minmax(100px,1fr))}.toolbar-note{display:none}}
@media(max-width:820px){.topbar{height:auto;min-height:60px;padding:10px 12px;gap:10px;flex-wrap:wrap}.brand-copy span{display:none}.instrument{padding-left:10px}.read-only{display:none}.top-actions button{padding:6px 7px}.workspace{height:auto;min-height:calc(100% - 60px);display:flex;flex-direction:column}.main{height:66vh;min-height:490px;padding:10px}.sidebar{overflow:visible;border-left:0;border-top:1px solid var(--line)}.chart-frame{min-height:280px}.stats{grid-template-columns:repeat(3,minmax(0,1fr))}.stat:nth-child(4),.stat:nth-child(5){display:none}}
@media(max-width:470px){.instrument{min-width:0}.instrument span{max-width:112px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.top-actions{width:100%;justify-content:flex-end;margin-top:-3px}.topbar{gap:8px}.stats{gap:5px}.stat{padding:7px}.stat b{font-size:12px}.stat label{font-size:8px}.toolbar .separator{margin:0 1px}.toolbar button{padding:5px 7px}.main{height:62vh;min-height:450px}}
</style>
</head>
<body>
<header class="topbar">
  <div class="brand"><div class="brand-mark">Z</div><div class="brand-copy"><b>ZTRADE <span style="color:#55d9a7">DESK</span></b><span>live market monitor</span></div></div>
  <div class="instrument"><b id="symbol">—</b><span id="exchange">Waiting for stream…</span></div>
  <div class="connection" id="connection"><i class="led"></i><span id="connectionText">Connecting</span></div>
  <div class="spacer"></div>
  <div class="read-only">Read-only feed · no exchange orders</div>
  <div class="top-actions"><button id="fullscreen" title="Toggle fullscreen (F)">⛶ Fullscreen</button><button id="exportPng" title="Save chart image">Export PNG</button></div>
</header>
<div class="workspace">
  <main class="main">
    <div class="toolbar">
      <div class="group" aria-label="Visible candles">
        <button data-window="50">50</button><button data-window="100">100</button><button data-window="250" class="active">250</button><button data-window="500">500</button><button data-window="all">All</button>
      </div>
      <span class="separator"></span>
      <select id="viewMode" aria-label="Chart view"><option value="candles">Candles</option><option value="line">Close line</option></select>
      <button id="follow" class="active" title="Keep the latest bar in view (L)">● Follow live</button>
      <button id="zoomIn" title="Zoom in">＋</button><button id="zoomOut" title="Zoom out">−</button><button id="fit">Fit</button>
      <span class="toolbar-note">Drag to pan · wheel to zoom · hover for OHLCV · F fullscreen</span>
    </div>
    <div class="stats">
      <div class="stat"><label>Last trade</label><b id="price">—</b><small id="priceSub">Exchange print</small></div>
      <div class="stat"><label>24h change</label><b id="change24h">—</b><small id="volume24h">24h volume —</small></div>
      <div class="stat"><label>Bid / ask spread</label><b id="spread">—</b><small id="vwap">Session trade VWAP —</small></div>
      <div class="stat"><label>Live print rate</label><b id="rate">—</b><small id="totalTrades">0 prints received</small></div>
      <div class="stat"><label>Feed latency</label><b id="latency">—</b><small id="serverTime">Waiting for timestamp</small></div>
    </div>
    <section class="chart-frame" id="chartFrame" aria-label="Live market chart">
      <div class="chart-title"><b id="chartName">Live price</b><span id="chartInterval">—</span></div>
      <canvas id="chart" aria-label="Interactive candlestick chart"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </section>
    <div class="chart-footer"><span id="chartStatus">Connecting to public exchange market data…</span><span><strong id="ohlcRibbon">O — · H — · L — · C —</strong></span></div>
  </main>
  <aside class="sidebar">
    <section class="side-section">
      <div class="side-title">Market microstructure <small id="quoteTime">Public feed</small></div>
      <div class="quote-grid">
        <div class="quote-box"><label>Best bid</label><b class="pos" id="bid">—</b></div>
        <div class="quote-box"><label>Best ask</label><b class="neg" id="ask">—</b></div>
      </div>
      <div class="metric-list"><span>Spread</span><b id="spreadSide">—</b><span>Top-book imbalance</span><b id="imbalance">Not supplied</b><span>Current bar volume</span><b id="barVolume">—</b><span>Current bar range</span><b id="barRange">—</b><span>Session trade VWAP</span><b id="sessionVwap">—</b><span>Data-coverage gaps</span><b id="gapCount">0</b></div>
      <div class="flow-line"><i class="flow-buy" id="buyFlow"></i><i class="flow-sell" id="sellFlow"></i></div>
      <div class="flow-legend"><span class="pos" id="buyVolume">Buyer-initiated volume —</span><span class="neg" id="sellVolume">Seller-initiated volume —</span></div>
    </section>
    <section class="side-section tape">
      <div class="side-title">Time & sales <small id="tapeCount">0 recent</small></div>
      <div class="tape-list" id="tapeList"><div class="empty">Waiting for the first exchange print…</div></div>
    </section>
    <section class="side-section">
      <div class="side-title">Paper execution <small>real feed · simulated fills</small></div>
      <div id="paperPanel"></div>
    </section>
    <section class="side-section"><div class="notice">Market data only. The dashboard has no API keys and cannot place exchange orders. Paper fills use the configured fee and slippage assumptions; they are not executable quotes.</div></section>
  </aside>
</div>
<script>
'use strict';
const $=id=>document.getElementById(id);
const canvas=$('chart'),ctx=canvas.getContext('2d',{alpha:false}),frame=$('chartFrame'),tooltip=$('tooltip');
let state=null,bars=[],mode='candles',follow=true,paused=false,windowSize=250,viewStart=0,viewEnd=0,hover=-1,drag=null,raf=0,lastSequence=0,snapshotInFlight=false;
let width=0,height=0,dpr=1;
const moneyFmt=new Intl.NumberFormat(undefined,{maximumFractionDigits:8});
function num(v){return v==null||!Number.isFinite(Number(v))?null:Number(v)}
function priceText(v){const x=num(v);if(x==null)return'—';const d=Math.abs(x)<.01?8:Math.abs(x)<1?6:Math.abs(x)<100?4:2;return x.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:d})}
function compact(v){const x=num(v);if(x==null)return'—';const a=Math.abs(x);return a>=1e9?(x/1e9).toFixed(2)+'b':a>=1e6?(x/1e6).toFixed(2)+'m':a>=1e3?(x/1e3).toFixed(2)+'k':x.toLocaleString(undefined,{maximumFractionDigits:4})}
function pct(v){const x=num(v);return x==null?'—':(x>0?'+':'')+x.toFixed(2)+'%'}
function timeShort(ms){if(!Number.isFinite(Number(ms)))return'—';return new Date(Number(ms)).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}
function utcLabel(seconds,span){const d=new Date(seconds*1000);return span<180?d.toLocaleTimeString(undefined,{timeZone:'UTC',hour:'2-digit',minute:'2-digit',hour12:false})+' UTC':d.toLocaleDateString(undefined,{timeZone:'UTC',month:'short',day:'2-digit',year:'2-digit'})}
function scheduleDraw(){if(paused||raf)return;raf=requestAnimationFrame(()=>{raf=0;draw()})}
function normalizeBar(c){return{timestamp:Number(c.timestamp),open:Number(c.open),high:Number(c.high),low:Number(c.low),close:Number(c.close),volume:Number(c.volume)||0}}
function mergeBars(incoming){if(!Array.isArray(incoming))return;for(const raw of incoming){if(!raw||!Number.isFinite(Number(raw.timestamp)))continue;const c=normalizeBar(raw);let lo=0,hi=bars.length;while(lo<hi){const mid=(lo+hi)>>1;if(bars[mid].timestamp<c.timestamp)lo=mid+1;else hi=mid}if(lo<bars.length&&bars[lo].timestamp===c.timestamp)bars[lo]=c;else bars.splice(lo,0,c)}if(bars.length>10000)bars=bars.slice(-10000);if(follow){viewEnd=bars.length;viewStart=Math.max(0,viewEnd-windowSize)}else{viewEnd=Math.min(viewEnd,bars.length);viewStart=Math.max(0,Math.min(viewStart,Math.max(0,viewEnd-1)))} }
function installSnapshot(s){state=s;if(Array.isArray(s.candles)){bars=s.candles.map(normalizeBar);viewEnd=bars.length;viewStart=Math.max(0,viewEnd-windowSize)}if(s.currentCandle)mergeBars([s.currentCandle]);lastSequence=Number(s.sequence)||lastSequence;updateUi();scheduleDraw()}
function applyUpdate(s){if(!state){installSnapshot(s);return}const sequence=Number(s.sequence)||0;if(lastSequence&&sequence>lastSequence+1)requestSnapshot();lastSequence=Math.max(lastSequence,sequence);state={...state,...s};if(s.candles)bars=s.candles.map(normalizeBar);else mergeBars(s.candleTail|| (s.currentCandle?[s.currentCandle]:[]));if(follow){viewEnd=bars.length;viewStart=Math.max(0,viewEnd-windowSize)}updateUi();scheduleDraw()}
async function requestSnapshot(){if(snapshotInFlight)return;snapshotInFlight=true;try{const r=await fetch('/api/snapshot',{cache:'no-store'});if(r.ok){const s=await r.json();if(!state||Number(s.sequence)>=Number(state.sequence))installSnapshot(s)}}catch{}finally{snapshotInFlight=false}}
function setConnection(value,detail){const el=$('connection');el.classList.remove('live','reconnecting','stopped');if(value==='live')el.classList.add('live');else if(value==='reconnecting'||value==='connecting')el.classList.add('reconnecting');else if(value==='stopped')el.classList.add('stopped');$('connectionText').textContent=value==='live'?'Live':value==='reconnecting'?'Reconnecting':value==='stopped'?'Stopped':'Connecting';$('chartStatus').textContent=detail||({live:'Live public market feed · visual updates coalesced to 20 Hz',reconnecting:'Feed interrupted · automatically reconnecting with backoff',stopped:'Live session stopped'}[value]||'Connecting to public exchange market data…')}
function updateUi(){if(!state)return;$('symbol').textContent=state.symbol||'—';$('exchange').textContent=`${state.exchange||'Exchange'} · ${state.interval||'—'} candles · public WebSocket`;$('chartInterval').textContent=state.interval||'';$('chartName').textContent=`${state.symbol||'Market'} · ${mode==='line'?'close':'OHLCV'}`;setConnection(state.connectionState,state.connectionDetail);
 const p=num(state.lastPrice),prev=bars.length>1?bars[bars.length-2].close:null;$('price').textContent=priceText(p);$('priceSub').textContent=state.currentCandle?`Bar open ${priceText(state.currentCandle.open)}`:'Exchange print';
 const change=num(state.change24hPercent);$('change24h').textContent=change==null?'—':pct(change);$('change24h').className=change==null?'':change>=0?'pos':'neg';$('volume24h').textContent=state.volume24h==null?'24h volume not supplied':`24h volume ${compact(state.volume24h)}`;
 $('bid').textContent=priceText(state.bid);$('ask').textContent=priceText(state.ask);const spread=num(state.spreadBasisPoints);$('spread').textContent=spread==null?'—':spread.toFixed(2)+' bp';$('spreadSide').textContent=spread==null?'Not supplied':spread.toFixed(2)+' bp';$('vwap').textContent=state.sessionVwap==null?'Session trade VWAP —':'Session VWAP '+priceText(state.sessionVwap);$('sessionVwap').textContent=priceText(state.sessionVwap);const imbalance=num(state.bookImbalance);$('imbalance').textContent=imbalance==null?'Not supplied':(imbalance>=0?'+':'')+(imbalance*100).toFixed(1)+'%';$('gapCount').textContent=compact(state.dataGapCount||0);
 const rate=num(state.tradeRatePerSecond);$('rate').textContent=rate==null?'—':rate.toFixed(1)+'/s';$('totalTrades').textContent=`${compact(state.totalTrades||0)} prints received`;$('latency').textContent=state.feedLatencyMilliseconds==null?'—':Math.round(state.feedLatencyMilliseconds)+' ms';$('serverTime').textContent=state.lastTradeTimeMilliseconds?`Exchange ${timeShort(state.lastTradeTimeMilliseconds)}`:'Waiting for trade';$('quoteTime').textContent=state.serverTimeMilliseconds?`Updated ${timeShort(state.serverTimeMilliseconds)}`:'Public feed';
 const c=state.currentCandle;if(c){$('ohlcRibbon').textContent=`O ${priceText(c.open)} · H ${priceText(c.high)} · L ${priceText(c.low)} · C ${priceText(c.close)}`;$('barVolume').textContent=compact(c.volume);$('barRange').textContent=priceText(c.high-c.low)}else{$('ohlcRibbon').textContent='O — · H — · L — · C —';$('barVolume').textContent='—';$('barRange').textContent='—'}
 const buy=num(state.buyVolume)||0,sell=num(state.sellVolume)||0,total=buy+sell,ratio=total>0?buy/total:.5;$('buyFlow').style.width=(ratio*100)+'%';$('sellFlow').style.width=((1-ratio)*100)+'%';$('buyVolume').textContent='Buy-side '+compact(buy);$('sellVolume').textContent='Sell-side '+compact(sell);renderTape(state.recentTrades||[]);renderPaper(state.paper);$('follow').classList.toggle('active',follow);document.querySelectorAll('[data-window]').forEach(b=>b.classList.toggle('active',b.dataset.window==='all'?windowSize>=bars.length:Number(b.dataset.window)===windowSize))}
function renderTape(trades){$('tapeCount').textContent=`${trades.length} recent`;const host=$('tapeList');if(!trades.length){host.innerHTML='<div class="empty">Waiting for the first exchange print…</div>';return}host.innerHTML=trades.slice().reverse().map(t=>{const side=['buy','sell'].includes(t.side)?t.side:'unknown';return`<div class="tape-row"><span class="time">${timeShort(t.timestampMilliseconds)}</span><span class="side-tag ${side}">${side}</span><span class="price ${side==='buy'?'pos':side==='sell'?'neg':''}">${priceText(t.price)}</span><span class="size">${compact(t.quantity)}</span></div>`}).join('')}
