function dimensions(){const r=canvas.getBoundingClientRect();const nextDpr=Math.min(window.devicePixelRatio||1,2);const w=Math.max(1,Math.floor(r.width*nextDpr)),h=Math.max(1,Math.floor(r.height*nextDpr));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}dpr=nextDpr;width=r.width;height=r.height;ctx.setTransform(dpr,0,0,dpr,0,0)}
function visibleRange(){if(!bars.length)return{a:0,b:0};const b=Math.max(1,Math.min(bars.length,viewEnd||bars.length));const a=Math.max(0,Math.min(b-1,viewStart));return{a,b}}
function intervalSeconds(){const match=/^(\d+)(s|m|hr|day)$/.exec(state?.interval||'');if(!match)return 0;return Number(match[1])*({s:1,m:60,hr:3600,day:86400}[match[2]])}
function draw(){dimensions();const w=width,h=height;if(w<10||h<10)return;ctx.fillStyle='#081319';ctx.fillRect(0,0,w,h);if(!bars.length){ctx.fillStyle='#82979d';ctx.font='12px system-ui';ctx.textAlign='center';ctx.fillText('Waiting for exchange candles…',w/2,h/2);return}
 const {a,b}=visibleRange(),count=b-a;if(!count)return;const left=68,right=16,top=32,bottom=29,volumeH=Math.max(36,Math.min(70,h*.16)),plotBottom=h-bottom-volumeH-10,plotTop=top,plotH=Math.max(30,plotBottom-plotTop),plotW=Math.max(20,w-left-right),slot=plotW/count;
 let low=Infinity,high=-Infinity,maxVolume=0;for(let i=a;i<b;i++){const c=bars[i];low=Math.min(low,c.low);high=Math.max(high,c.high);maxVolume=Math.max(maxVolume,c.volume)}if(!Number.isFinite(low)||!Number.isFinite(high)){low=0;high=1}if(high===low){const pad=Math.abs(high)*.002||1;high+=pad;low-=pad}const pad=(high-low)*.06;high+=pad;low-=pad;const y=v=>plotTop+(high-v)/(high-low)*plotH;const x=i=>left+(i-a+.5)*slot;
 ctx.font='9px ui-monospace,monospace';ctx.textAlign='right';ctx.textBaseline='middle';for(let k=0;k<=5;k++){const value=high-(high-low)*k/5,yy=plotTop+plotH*k/5;ctx.strokeStyle='#21343a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillStyle='#91a5a9';ctx.fillText(priceText(value),left-8,yy)}
 ctx.strokeStyle='#1d3036';ctx.beginPath();ctx.moveTo(left,plotBottom+8);ctx.lineTo(w-right,plotBottom+8);ctx.stroke();const volumeTop=plotBottom+17,volumeBottom=h-bottom;for(let i=a;i<b;i++){const c=bars[i],cx=x(i),up=c.close>=c.open,color=up?'#42d6a0':'#ff687a';const vh=maxVolume?Math.max(1,(c.volume/maxVolume)*(volumeBottom-volumeTop)):0;ctx.fillStyle=up?'#42d6a077':'#ff687a77';ctx.fillRect(cx-Math.max(.5,slot*.28),volumeBottom-vh,Math.max(1,slot*.56),vh);if(mode==='line')continue;ctx.strokeStyle=color;ctx.lineWidth=Math.max(1,Math.min(1.5,slot*.18));ctx.beginPath();ctx.moveTo(cx,y(c.high));ctx.lineTo(cx,y(c.low));ctx.stroke();const oy=y(c.open),cy=y(c.close),bodyTop=Math.min(oy,cy),bodyH=Math.max(1,Math.abs(oy-cy)),bodyW=Math.max(1,Math.min(12,slot*.62));ctx.fillStyle=up?'#42d6a0':'#ff687a';ctx.fillRect(cx-bodyW/2,bodyTop,bodyW,bodyH)}
 if(mode==='line'){ctx.beginPath();let started=false;for(let i=a;i<b;i++){const xx=x(i),yy=y(bars[i].close);if(!started){ctx.moveTo(xx,yy);started=true}else ctx.lineTo(xx,yy)}ctx.strokeStyle='#53d4c4';ctx.lineWidth=1.6;ctx.stroke();ctx.lineTo(x(b-1),plotBottom);ctx.lineTo(x(a),plotBottom);ctx.closePath();ctx.fillStyle='#48c8d817';ctx.fill()}
 const expectedStep=intervalSeconds();if(expectedStep>0)for(let i=a+1;i<b;i++){if(bars[i].timestamp-bars[i-1].timestamp<=expectedStep)continue;const gx=(x(i-1)+x(i))/2,gapW=Math.max(1,Math.min(12,slot*.35));ctx.fillStyle='#f4bd6214';ctx.fillRect(gx-gapW/2,plotTop,gapW,volumeBottom-plotTop);ctx.strokeStyle='#f4bd62aa';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(gx,plotTop);ctx.lineTo(gx,volumeBottom);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#f4bd62';ctx.textAlign='center';ctx.textBaseline='top';ctx.font='8px system-ui';ctx.fillText('GAP',gx,plotTop+2)}
 const ticks=Math.min(6,count);ctx.textAlign='center';ctx.textBaseline='top';ctx.fillStyle='#82979d';ctx.font='9px system-ui';for(let k=0;k<=ticks;k++){const i=Math.min(b-1,a+Math.floor((count-1)*k/Math.max(1,ticks)));const xx=x(i);ctx.strokeStyle='#273940';ctx.beginPath();ctx.moveTo(xx,volumeBottom+2);ctx.lineTo(xx,volumeBottom+5);ctx.stroke();ctx.fillText(utcLabel(bars[i].timestamp,count),xx,volumeBottom+7)}
 ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillStyle='#82979d';ctx.font='8px system-ui';ctx.fillText('VOL',left+3,volumeTop+10);
 if(hover>=a&&hover<b){const xx=x(hover),c=bars[hover];ctx.strokeStyle='#a7c3c855';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(xx,plotTop);ctx.lineTo(xx,volumeBottom);ctx.stroke();ctx.setLineDash([]);const yy=y(c.close);ctx.fillStyle='#e3eff0';ctx.beginPath();ctx.arc(xx,yy,3,0,Math.PI*2);ctx.fill();showTooltip(c,xx,yy,w,h)}else tooltip.style.display='none';
 if(state?.lastPrice!=null){const last=num(state.lastPrice);if(last>=low&&last<=high){const yy=y(last);ctx.strokeStyle='#48c8d899';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#48c8d8';ctx.fillRect(w-right-59,yy-8,59,16);ctx.fillStyle='#062027';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='9px ui-monospace,monospace';ctx.fillText(priceText(last),w-right-29.5,yy)}}
}
function showTooltip(c,x,y,w,h){tooltip.innerHTML=`<div class="tooltip-head"><span>${utcLabel(c.timestamp,1)}</span><span>${c.close>=c.open?'▲':'▼'} ${priceText(c.close)}</span></div><div class="tooltip-grid"><span>Open <b>${priceText(c.open)}</b></span><span>High <b>${priceText(c.high)}</b></span><span>Low <b>${priceText(c.low)}</b></span><span>Close <b>${priceText(c.close)}</b></span><span>Volume <b>${compact(c.volume)}</b></span><span>Range <b>${priceText(c.high-c.low)}</b></span></div>`;tooltip.style.display='block';const tw=tooltip.offsetWidth,th=tooltip.offsetHeight;tooltip.style.left=Math.max(5,Math.min(w-tw-6,x+14))+'px';tooltip.style.top=Math.max(5,Math.min(h-th-6,y+12))+'px'}
function point(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function indexAt(px){const {a,b}=visibleRange();const left=68,right=16,plotW=width-left-right;return Math.max(a,Math.min(b-1,Math.floor(a+(px-left)/plotW*(b-a))))}
canvas.addEventListener('pointerdown',e=>{const p=point(e);drag={x:p.x,start:viewStart,end:viewEnd,follow};follow=false;$('follow').classList.remove('active');canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{const p=point(e);if(drag){const span=Math.max(1,drag.end-drag.start),slot=(width-84)/span,delta=Math.round((drag.x-p.x)/Math.max(1,slot));viewStart=Math.max(0,Math.min(Math.max(0,bars.length-span),drag.start+delta));viewEnd=viewStart+span;hover=-1;scheduleDraw();return}const i=indexAt(p.x);hover=(p.x<68||p.x>width-16||p.y<25||p.y>height-25)?-1:i;if(hover>=0){const c=bars[hover];$('ohlcRibbon').textContent=`O ${priceText(c.open)} · H ${priceText(c.high)} · L ${priceText(c.low)} · C ${priceText(c.close)}`}else if(state?.currentCandle){const c=state.currentCandle;$('ohlcRibbon').textContent=`O ${priceText(c.open)} · H ${priceText(c.high)} · L ${priceText(c.low)} · C ${priceText(c.close)}`}scheduleDraw()});
function endDrag(){if(drag){drag=null;scheduleDraw()}}canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);canvas.addEventListener('pointerleave',()=>{if(!drag){hover=-1;tooltip.style.display='none';scheduleDraw()}});
canvas.addEventListener('wheel',e=>{e.preventDefault();if(!bars.length)return;const anchor=indexAt(point(e).x),span=Math.max(20,viewEnd-viewStart),next=Math.max(20,Math.min(bars.length,Math.round(span*(e.deltaY>0?1.18:.84)))),ratio=(anchor-viewStart)/span;follow=false;windowSize=next;viewStart=Math.max(0,Math.min(bars.length-next,Math.round(anchor-ratio*next)));viewEnd=Math.min(bars.length,viewStart+next);$('follow').classList.remove('active');scheduleDraw()},{passive:false});
function setWindow(value){follow=false;windowSize=value==='all'?Math.max(1,bars.length):Number(value);viewEnd=bars.length;viewStart=Math.max(0,viewEnd-windowSize);$('follow').classList.remove('active');updateUi();scheduleDraw()}
document.querySelectorAll('[data-window]').forEach(b=>b.addEventListener('click',()=>setWindow(b.dataset.window)));
$('follow').addEventListener('click',()=>{follow=!follow;if(follow){viewEnd=bars.length;viewStart=Math.max(0,viewEnd-windowSize)}updateUi();scheduleDraw()});$('viewMode').addEventListener('change',e=>{mode=e.target.value;$('chartName').textContent=`${state?.symbol||'Market'} · ${mode==='line'?'close':'OHLCV'}`;scheduleDraw()});
$('zoomIn').addEventListener('click',()=>setWindow(Math.max(20,Math.floor((viewEnd-viewStart)*.8))));$('zoomOut').addEventListener('click',()=>setWindow(Math.min(Math.max(1,bars.length),Math.ceil((viewEnd-viewStart)*1.25))));$('fit').addEventListener('click',()=>setWindow('all'));
$('fullscreen').addEventListener('click',toggleFullscreen);async function toggleFullscreen(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen()}catch{}}
$('exportPng').addEventListener('click',()=>{try{const a=document.createElement('a');a.download=`${(state?.symbol||'market').replace(/[^a-z0-9_-]/gi,'-')}-live.png`;a.href=canvas.toDataURL('image/png');a.click()}catch{$('chartStatus').textContent='PNG export was blocked by this browser.'}});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(e.key.toLowerCase()==='f')toggleFullscreen();else if(e.key.toLowerCase()==='l')$('follow').click();else if(e.key==='+'||e.key==='=')$('zoomIn').click();else if(e.key==='-')$('zoomOut').click();else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){const step=e.shiftKey?10:1,span=Math.max(1,viewEnd-viewStart);follow=false;viewStart=Math.max(0,Math.min(Math.max(0,bars.length-span),viewStart+(e.key==='ArrowLeft'?-step:step)));viewEnd=viewStart+span;updateUi();scheduleDraw()}});
